package dev.seaglass.mobile

import android.app.Activity
import android.os.Bundle

/**
 * Target of a tap on the notification (#163). No UI: it asks Rust for "Now playing" (which
 * tells the UI, or holds it until the WebView is ready), brings the app back to the
 * foreground like the launcher, then closes. The main activity is generated by Tauri:
 * going through here avoids touching it.
 */
class NowPlayingActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        Playback.onMain { Playback.command("openNowPlaying") }
        packageManager.getLaunchIntentForPackage(packageName)?.let(::startActivity)
        finish()
    }
}
